/**
 * The session's `kemPk`, the key the existing device seals to.
 */
ScaasUaStatus scaas_ua_link_session_kem_pk(const ScaasUaLinkSession *s, uint8_t *out1601);

/**
 * The 8-digit short code both screens show (NUL-terminated).
 */
